import{_ as o,o as a,c as t,ag as i}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"音乐源常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"allmusic/troubleshooting.md","filePath":"allmusic/troubleshooting.md"}'),r={name:"allmusic/troubleshooting.md"};function l(s,e,c,u,h,n){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="音乐源常见问题" tabindex="-1">音乐源常见问题 <a class="header-anchor" href="#音乐源常见问题" aria-label="Permalink to &quot;音乐源常见问题&quot;">​</a></h1><h2 id="提示找不到音乐-api" tabindex="-1">提示找不到音乐 API <a class="header-anchor" href="#提示找不到音乐-api" aria-label="Permalink to &quot;提示找不到音乐 API&quot;">​</a></h2><p>确认 JAR 位于 AllMusic 实际数据目录的 <code>api/</code> 中，并正常重启加载。<code>qqmusic</code> 与 <code>kugou</code> 都是小写 API ID。如果日志中没有加载成功的记录，先处理目录、JAR 或接口版本问题，再修改 <code>defaultApi</code>。</p><h2 id="出现-nosuchmethoderror-或-classnotfoundexception" tabindex="-1">出现 NoSuchMethodError 或 ClassNotFoundException <a class="header-anchor" href="#出现-nosuchmethoderror-或-classnotfoundexception" aria-label="Permalink to &quot;出现 NoSuchMethodError 或 ClassNotFoundException&quot;">​</a></h2><p>音乐源依赖当前 AllMusic 核心接口。使用与运行版本匹配的发布包，或把对应核心 JAR 放入音乐源源码的 <code>libs/</code> 后重新构建。不要把 AllMusic 核心再打包到音乐源中，也不要混用多个平台的 AllMusic 安装包。</p><h2 id="搜索有结果-播放却失败" tabindex="-1">搜索有结果，播放却失败 <a class="header-anchor" href="#搜索有结果-播放却失败" aria-label="Permalink to &quot;搜索有结果，播放却失败&quot;">​</a></h2><p>搜索结果只表示找到歌曲，播放还需要取得有效音频地址。检查 Cookie 是否过期、账号权限是否满足，以及服务端能否连接音乐平台。歌词或封面成功不表示音频地址一定可用。两种扩展均依赖平台正常返回的免费或已授权资源。</p><h2 id="游戏里没有声音" tabindex="-1">游戏里没有声音 <a class="header-anchor" href="#游戏里没有声音" aria-label="Permalink to &quot;游戏里没有声音&quot;">​</a></h2><p>确认玩家客户端安装了与服务端匹配的 AllMusic 模组，并检查玩家是否处于静音、黑名单或被排除的服务器。先按 AllMusic 本身的命令和播放配置排查，再处理 BiliMusicBridge 的直播连接。</p><h2 id="两种音乐源同时使用时如何设置-cookie" tabindex="-1">两种音乐源同时使用时如何设置 Cookie <a class="header-anchor" href="#两种音乐源同时使用时如何设置-cookie" aria-label="Permalink to &quot;两种音乐源同时使用时如何设置 Cookie&quot;">​</a></h2><p>QQMusic 使用 AllMusic 加载的 Cookie 列表。Kugou 可以通过 <code>ALLMUSIC_KUGOU_COOKIE</code> 独立配置，以减少不同平台同名 Cookie 之间的混淆。具体优先级见 <a href="./kugou.html#cookie-来源">Kugou 文档</a>。</p><h2 id="如何反馈问题" tabindex="-1">如何反馈问题 <a class="header-anchor" href="#如何反馈问题" aria-label="Permalink to &quot;如何反馈问题&quot;">​</a></h2><p>提供运行平台、Java 与 AllMusic 版本、音乐源版本、相关错误日志，以及不含账号信息的歌曲标识。QQMusic 问题提交到 <a href="https://github.com/hutuyee/AllMusic_QQMusic/issues" target="_blank" rel="noreferrer">AllMusic_QQMusic Issues</a>，酷狗问题提交到 <a href="https://github.com/hutuyee/AllMusic_Kugou/issues" target="_blank" rel="noreferrer">AllMusic_Kugou Issues</a>。</p>',13)])])}const _=o(r,[["render",l]]);export{p as __pageData,_ as default};
